def gelu(x: torch.Tensor) -> torch.Tensor:
    # x: 任意形状的 float32 张量
    # TODO: 精确 erf 版本 GELU，返回与 x 同形状的张量
    return x
$code$, $code$import math

import torch

def gelu(x: torch.Tensor) -> torch.Tensor:
    return 0.5 * x * (1.0 + torch.erf(x / math.sqrt(2.0)))
