-- 实现数值稳定的交叉熵损失  (medium / function / pytorch)
insert into public.coding_problems (
  id, title, slug, difficulty, category, description, constraints,
  starter_code, solution_code, function_name, language, time_limit_ms,
  memory_limit_mb, comparison_mode, tolerance, is_published, is_featured,
  evaluation_mode, entrypoint_type, entrypoint_name, framework,
  resource_profile, evaluator_config
) values (
  'b1000000-0000-4000-8000-000000000136', $t$实现数值稳定的交叉熵损失$t$, 'cross-entropy-loss',
  'medium', 'algorithms',
  $d$从零实现多分类交叉熵损失（mean reduction）。给定未归一化的 logits 和整数类别标签，返回标量损失：

    loss = mean_i( logsumexp(logits[i]) - logits[i, targets[i]] )

要求：
- 实现必须数值稳定：输入 logits 含 ±1000 量级的极端值时不能产生 inf/NaN（提示：减去每行最大值再做 log-sum-exp）；
- 不要直接调用 torch.nn.functional.cross_entropy / torch.nn.CrossEntropyLoss；
- 计算必须可微（对 logits 的梯度应为 softmax(labels) - onehot(targets) 的批均值）；
- 返回形状为标量张量（torch.shape 为 []）。$d$,
  $c$logits 为 float32 张量 (B, V)，2 <= B <= 8，2 <= V <= 64；targets 为 int64 张量 (B,)，0 <= targets[i] < V；|logits| <= 1000。$c$,
  $code$import torch

def cross_entropy(logits: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
    # logits: (B, V) float32，未归一化
    # targets: (B,) int64，类别索引
    # TODO: 返回标量损失（mean reduction），要求数值稳定
    return (logits + targets.float().sum()).sum() * 0.0
$code$, $code$import torch

def cross_entropy(logits: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
    lse = torch.logsumexp(logits, dim=-1)
    picked = logits.gather(1, targets.unsqueeze(1)).squeeze(1)
    return (lse - picked).mean()
$code$,
  'cross_entropy', 'python', 15000, 512,
  'numeric', 0.0001, true, false,
  'function', 'function', 'cross_entropy',
  'pytorch', 'ml_cpu_small',
  '{"comparison":"allclose","rtol":0.0001,"atol":1e-05,"check_shape":true,"check_dtype":false,"check_gradient":true}'
);

