-- 实现滑动窗口注意力  (medium / function / pytorch)
insert into public.coding_problems (
  id, title, slug, difficulty, category, description, constraints,
  starter_code, solution_code, function_name, language, time_limit_ms,
  memory_limit_mb, comparison_mode, tolerance, is_published, is_featured,
  evaluation_mode, entrypoint_type, entrypoint_name, framework,
  resource_profile, evaluator_config
) values (
  'b1000000-0000-4000-8000-000000000148', $t$实现滑动窗口注意力$t$, 'sliding-window-attention',
  'medium', 'transformer',
  $d$实现滑动窗口（局部带状）注意力。位置 i 只能 attend 到窗口内的位置：

    i - window + 1 <= j <= i（j 需在 [0, S) 内）

即窗口大小为 window（含当前位置本身）。窗口外的注意力权重强制为 0，等价于在 scores 上把非法位置置为 -inf 后做 softmax：

    scores = q @ k^T / sqrt(D)
    scores[非法位置] = -inf
    out = softmax(scores, dim=-1) @ v

输入形状：q/k/v 均为 (B, H, S, D)，输出形状与 q 相同。

要求：
- 不要调用 torch.nn.functional.scaled_dot_product_attention；
- 计算必须可微；
- 注意 -inf 位置的 softmax 权重必须严格为 0（不产生 NaN）。$d$,
  $c$B, H <= 2；1 <= window <= S <= 32；D ∈ {8, 16}，全为 float32。$c$,
  $code$import torch

def sliding_window_attention(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, window: int) -> torch.Tensor:
    # q/k/v: (B, H, S, D)；window: 窗口大小（含当前位置）
    # TODO: 返回 (B, H, S, D)
    return q
$code$, $code$import math

import torch

def sliding_window_attention(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, window: int) -> torch.Tensor:
    S = q.shape[-2]
    scores = q @ k.transpose(-2, -1) / math.sqrt(q.shape[-1])
    idx = torch.arange(S)
    mask = (idx.unsqueeze(0) >= idx.unsqueeze(1) - window + 1) & (idx.unsqueeze(0) <= idx.unsqueeze(1))
    scores = scores.masked_fill(~mask, float("-inf"))
    attn = torch.softmax(scores, dim=-1)
    return attn @ v
$code$,
  'sliding_window_attention', 'python', 15000, 512,
  'numeric', 0.0001, true, false,
  'function', 'function', 'sliding_window_attention',
  'pytorch', 'ml_cpu_small',
  '{"comparison":"allclose","rtol":0.0001,"atol":1e-05,"check_shape":true,"check_dtype":false,"check_gradient":true}'
);

