-- 实现 LoRA 低秩适配层  (medium / class / pytorch)
insert into public.coding_problems (
  id, title, slug, difficulty, category, description, constraints,
  starter_code, solution_code, function_name, language, time_limit_ms,
  memory_limit_mb, comparison_mode, tolerance, is_published, is_featured,
  evaluation_mode, entrypoint_type, entrypoint_name, framework,
  resource_profile, evaluator_config
) values (
  'b1000000-0000-4000-8000-000000000151', $t$实现 LoRA 低秩适配层$t$, 'lora-layer',
  'medium', 'transformer',
  $d$实现 LoRA（Low-Rank Adaptation）。冻结的基础权重旁路挂上一个低秩分解的更新：

    y = x @ W^T + (x @ A^T @ B^T) * (alpha / r)

其中 W 为 (out_features, in_features) 的基础权重（理想情况下冻结，本题仅要求参与前向），A 为 (r, in_features)，B 为 (out_features, r)，r 为秩（A.shape[0]），alpha 为缩放超参数。输出形状 (B, out_features)。

要求：
- 类必须继承 torch.nn.Module；
- `__init__(self, base_weight, lora_A, lora_B, alpha: float)`，把三个张量注册为名为 `base_weight`、`lora_A`、`lora_B` 的 nn.Parameter（梯度检查按这三个名字进行）；
- 秩 r 必须从 lora_A 的形状推导，缩放系数为 alpha / r；
- 不要调用 torch.nn.Linear。$d$,
  $c$base_weight 为 (out, in) float32；lora_A 为 (r, in)，lora_B 为 (out, r)，1 <= r <= 8；x 为 (B, in) float32，B <= 16，in/out <= 64。$c$,
  $code$import torch
import torch.nn as nn

class LoRALinear(nn.Module):
    def __init__(self, base_weight: torch.Tensor, lora_A: torch.Tensor, lora_B: torch.Tensor, alpha: float) -> None:
        # base_weight: (out, in)；lora_A: (r, in)；lora_B: (out, r)；alpha: 缩放超参
        # TODO: 注册为名为 base_weight / lora_A / lora_B 的 nn.Parameter
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # x: (B, in)
        # TODO: 返回 (B, out)
        return x
$code$, $code$import torch
import torch.nn as nn

class LoRALinear(nn.Module):
    def __init__(self, base_weight: torch.Tensor, lora_A: torch.Tensor, lora_B: torch.Tensor, alpha: float) -> None:
        super().__init__()
        self.base_weight = nn.Parameter(base_weight)
        self.lora_A = nn.Parameter(lora_A)
        self.lora_B = nn.Parameter(lora_B)
        self.alpha = alpha
        self.rank = lora_A.shape[0]

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        base = x @ self.base_weight.T
        delta = (x @ self.lora_A.T @ self.lora_B.T) * (self.alpha / self.rank)
        return base + delta
$code$,
  'LoRALinear', 'python', 15000, 512,
  'numeric', 0.0001, true, false,
  'class', 'class', 'LoRALinear',
  'pytorch', 'ml_cpu_small',
  '{"comparison":"allclose","rtol":0.0001,"atol":1e-05,"check_shape":true,"check_dtype":false,"check_gradient":true}'
);

