-- 实现 INT8 对称量化（per-tensor）  (medium / function / pytorch)
insert into public.coding_problems (
  id, title, slug, difficulty, category, description, constraints,
  starter_code, solution_code, function_name, language, time_limit_ms,
  memory_limit_mb, comparison_mode, tolerance, is_published, is_featured,
  evaluation_mode, entrypoint_type, entrypoint_name, framework,
  resource_profile, evaluator_config
) values (
  'b1000000-0000-4000-8000-000000000158', $t$实现 INT8 对称量化（per-tensor）$t$, 'int8-quantize',
  'medium', 'transformer',
  $d$实现大模型推理部署中最常用的 per-tensor 对称量化与反量化：

    amax = max(|w|)
    scale = amax / 127                # amax == 0 时取 scale = 1.0
    q = clamp(round(w / scale), -127, 127).to(int64)
    w_hat = q.to(float32) * scale     # 反量化近似

返回: 元组 (w_hat, scale)，w_hat 为与 w 同形状的 float32 张量，scale 为 Python float。

要求：
- round 用 torch.round（银行家舍入即可，与参考实现一致）；
- clamp 在 round 之后、转 int64 之前；
- 不要调用 torch.quantize_per_tensor 等现成量化 API；
- 全零张量是合法输入（scale 兜底为 1.0，此时 w_hat 必须全零）。$d$,
  $c$w 为 float32 张量（ndim <= 4，元素数 <= 4096），|w_i| <= 1000。$c$,
  $code$import torch

def quantize_dequantize(w: torch.Tensor):
    # w: 任意形状 float32
    # TODO: 返回 (w_hat, scale)
    return w, 1.0
$code$, $code$import torch

def quantize_dequantize(w: torch.Tensor):
    amax = w.abs().max().item()
    scale = amax / 127.0 if amax > 0 else 1.0
    q = torch.round(w / scale).clamp(-127, 127).to(torch.int64)
    w_hat = q.to(torch.float32) * scale
    return w_hat, float(scale)
$code$,
  'quantize_dequantize', 'python', 15000, 512,
  'numeric', 0.0001, true, false,
  'function', 'function', 'quantize_dequantize',
  'pytorch', 'ml_cpu_small',
  '{"comparison":"allclose","rtol":0.0001,"atol":1e-05,"check_shape":true,"check_dtype":false,"check_gradient":false}'
);

